import type { SiteHistoryEntry } from "./types";

export const SITE_HISTORY_MEXICO_1: Record<string, SiteHistoryEntry> = {
  "oaxaca-mx": {
    why: "Seventeen degrees north would read as tropical heat if the Valles Centrales sat near sea level. At about 1555 m the lapse rate knocks afternoon highs into the low-to-mid 20s °C for most months, while the Sierra Madre de Oaxaca and Sierra Madre del Sur blunt Gulf and Pacific moisture except when summer monsoon convection builds on the ridges. East–west valley axes still funnel Isthmus air; orographic lift then dumps short, hard afternoon storms. Dry-season light is hard and clear. Wet-season evenings usually recover after the cells collapse.",
    history: [
      "Maize terraces and milpa already occupied the Valles Centrales long before a Spanish plaza. Zapotec planners carved Monte Albán from a mountain above the Atoyac, holding regional power from about 500 BCE until the city faded after 850 CE. Mixtec polities later entered the valleys through marriage alliance and war, while a Mexica garrison named the river junction Huaxyacac in the late 1400s. Village states such as Zaachila stayed modest beside the abandoned mountaintop, yet the same volcanic-sedimentary soils kept feeding maize, beans, squash, and hillside agave.",
      "Francisco Orozco’s column reached Huaxyacac in 1521. In 1529 the Crown ordered Villa de Antequera on a checkerboard trace laid by Alonso García Bravo between the Jalatlaco, the Atoyac, and Cerro del Fortín. Dominicans arrived the same year to build San Pablo and to evangelize Zapotec and Mixtec towns already organized around markets and milpa. City rank came in 1532; a bishopric followed in 1535. Cortés tried to fold the site into his Marquesado del Valle and failed. The colonial city grew as a control point on the Tehuantepec road, not as an empty stage.",
      "Independence renamed the city Oaxaca; de Juárez was added in 1872 for Benito Juárez, born in Guelatao. Reform laws, railway links, and later federal tourism policy recast the historic core as heritage, while Mixtec and Zapotec municipalities kept communal land and craft economies in the surrounding valleys. UNESCO inscribed the centro histórico with Monte Albán in 1987. Mezcal, Guelaguetza, and archaeology now draw visitors, but the older work of milpa, markets, and village governance still organizes the year more than any festival calendar.",
    ],
    deepTitle: "Zapotec valley city",
    deep: [
      "Monte Albán’s north–south esplanade, ball court, and carved Danzantes record a Zapotec state that terraced hillsides, built dams, and wrote in stone. After the Classic decline, Mixtec elites reused tombs and raised smaller centers such as Mitla and Yagul rather than restoring one capital. The Spanish city sits downslope from that sacred topography, close enough that the archaeological zone remains a working neighbor rather than a distant ruin. INAH stewardship and village land around the mountain still collide with visitor traffic, looting pressure, and the slow work of excavation.",
      "Dominican convents, the cathedral, and a grid of portals around the zócalo mark Antequera as a planned Spanish city dropped onto a densely farmed Indigenous landscape. Evangelization did not erase Zapotec or Mixtec languages; it rerouted tribute, labor, and feast days through parish and cabildo. Earthquake damage, notably in 1931 and 2017, repeatedly stripped plaster and forced INAH repairs that keep the centro looking colonial while the living city spreads into former ejido and orchard land. The checkerboard still organizes walking, markets, and political protest.",
      "Nineteenth-century Reform attacked corporate Church and Indigenous community holdings, yet many Central Valley municipalities retained usos y costumbres and communal lands that still structure mezcal palenques, weaving towns, and milpa. Juárez’s Oaxacan origin is civic memory, not a simple liberal triumph; land conflict continued through the Revolution and into contemporary disputes over mining, wind, and tourism. Guelaguetza, rebuilt as a state spectacle in the twentieth century, sits on older Zapotec practices of reciprocal giving that villages still run on their own calendars.",
      "Heritage tourism and the mezcal boom have raised land prices in the centro and along the Etla and Tlacolula arms without replacing village agriculture. Teotitlán del Valle, San Bartolo Coyotepec, and dozens of other towns sell craft into the city while keeping fields on the valley floor. Smoke from late-dry-season burns and brick kilns is a seasonal public-health fact, not scenery. Oaxaca City remains a Zapotec–Mixtec valley capital under visitor pressure, not a climate postcard with ruins attached.",
    ],
  },

  "san-cristobal-mx": {
    why: "At 16–17°N this basin should feel like lowland Chiapas heat. Elevation near 2200 m and a closed highland bowl reverse that: July afternoons often stay near 20–23 °C, while calm winter nights pool cold air on the floor until mornings brush frost. Cloud-forest ridges at 2400–2800 m wring Gulf and Pacific moisture into mist and a long wet season. The result is a cool, cloudy highland climate, not the Cuernavaca-style spring that tourism copy prefers.",
    history: [
      "Tzotzil and Tzeltal Maya already farmed the Altos around the Jovel basin when Spanish columns climbed from the Grijalva lowlands. The valley’s own names, Job’el or Jovel, describe pasture and cloud, not emptiness. Zoque country lay west; Chiapanec towns held the river depression. Highland maize, sheep after contact, and later apple and vegetable plots used the same cool soils. Markets linked ridge hamlets to the basin floor long before a Spanish villa claimed the pasture as a conquest camp.",
      "Diego de Mazariegos founded Villa Real de Chiapa on 31 March 1528 after campaigns against Zoque, Chiapanec, Tzotzil, and Tzeltal polities. The settlement became Ciudad Real in 1536 and the colonial capital of Chiapas. Encomiendas and Dominican, Mercedarian, and Franciscan convents extracted tribute from surrounding pueblos. Bartolomé de las Casas reached the city in 1541 as bishop; reducciones concentrated Tzotzil and Tzeltal families into nucleated towns that still ring San Cristóbal. The city lived on highland production more than on mines.",
      "The name San Cristóbal de las Casas settled in the nineteenth century; state capital functions moved to warmer Tuxtla Gutiérrez in 1892. INAH declared a zona de monumentos in 1986. The 1994 EZLN uprising, launched in nearby municipalities, made the Altos a national political stage and accelerated both Indigenous organizing and visitor traffic. Weaving towns such as Chamula and Zinacantán remain Tzotzil civic centers, not craft annexes. Tourism, NGOs, and continued land pressure now share a colonial street plan built on Maya highland agriculture.",
    ],
    deepTitle: "Maya highland seat",
    deep: [
      "Ciudad Real was a small Spanish and ladino island in a Tzotzil–Tzeltal hinterland. Without rich mines, the city depended on grain, cloth, and labor taken from pueblos de indios through tribute and later through highland fincas. Dominican Santo Domingo, the cathedral, and barrio churches mapped that extraction in stone. Rigid caste geography lasted into the twentieth century: ladino families in the centro, Maya communities on the ridges, markets as the daily contact zone. That structure is historical fact, not local color.",
      "Reducciones of the 1540s forced dispersed hamlets into grid towns with a church and a cabildo, a colonial tool still visible in Chamula, Tenejapa, Zinacantán, and Huixtán. Civil-religious cargo systems, milpa, and later Protestant conversions reshaped those towns from inside. Mid-century land hunger sent Tzotzil and Tzeltal families into the Lacandón forest. San Cristóbal remained the place to sell, litigate, and buy manufactured goods, including the amber and textiles that visitors now treat as the whole story. Understanding the city means reading those municipalities, their land titles, and their languages, not only stalls on Real de Guadalupe.",
      "Chiapas entered the Mexican republic in 1824 after a brief annexation debate. Conservative Ciudad Real backed centralist causes while coffee and cattle fincas expanded on Indigenous land in the nineteenth and early twentieth centuries. Bishop Samuel Ruiz, arriving in 1960, aligned parts of the diocese with highland Maya organizing. On 1 January 1994 the EZLN occupied San Cristóbal for a day and held the Altos in national view. Military, tourist, and NGO presence all thickened afterward. The uprising was a land-and-autonomy war, not a folklore event.",
      "Pueblo Mágico branding after 2003 packed the centro with hotels while Maya vendors and displaced families filled peripheral colonias. Walking weather is genuine; so are wet-season landslides on the ridge roads and winter nights that demand heat. Textile production in Tzotzil and Tzeltal towns is skilled wage and household work under market pressure, not a timeless costume. Municipal autonomy, language, and land are the first facts; the cool basin is why a colonial capital sat here in the first place.",
    ],
  },

  "cuernavaca-mx": {
    why: "South-facing volcanic benches at about 1510 m sit below Popocatépetl and Iztaccíhuatl yet above the true tierra caliente of Morelos. That elevation trims Mexico City’s chill while the slope aspect adds winter sun the higher basin does not get. Afternoons run warmer than the capital; nights still drop into the teens °C. Summer convection off the volcanoes rinses the air most evenings. The eternal-spring reputation is a slope-and-lapse-rate fact later turned into a slogan.",
    history: [
      "Tlahuica lords ran Cuauhnáhuac as a tribute center in the Postclassic, collecting from towns near the trees, as the Nahuatl name has it. Mexica power later overlaid that señorío. Chalcatzingo’s earlier Formative reliefs already show how long people have used Morelos’s volcanic soils and irrigation. When Cortés’s forces took the slope, they wrecked the tlatocayancalli, the house where streams and tribute met, and raised a fortress-palace on its foundations between the early 1520s and 1535. Power stayed on the same bench.",
      "The Palacio de Cortés became seat of the Marquesado del Valle, then barracks, jail, and Morelos state offices. José de la Borda’s late-eighteenth-century garden made the town a botanical retreat for Taxco silver wealth. Alexander von Humboldt, passing in 1803, wrote of a tierra templada of perpetual spring, a phrase later used to sell the climate. Maximilian and Carlota wintered at Jardín Borda in 1865–66. Sugar haciendas in the warmer valleys below fed Mexico City and bound Morelos to plantation labor.",
      "Emiliano Zapata’s Plan de Ayala and the Morelos campaign made this state the center of agrarian revolution. Land reform broke many cane haciendas into ejidos, then late-twentieth-century sprawl from Mexico City climbed the same south-facing slope. Weekend houses, language schools, and expressway access recast Cuernavaca as a climate suburb as much as a colonial city. INAH now runs the palace as the Museo Regional de los Pueblos de Morelos after the 2017 earthquake closed it for years. The Tlahuica ground is still under the museum floor.",
    ],
    deepTitle: "Tlahuica slope town",
    deep: [
      "Cuauhnáhuac mattered because water and maize concentrated on a temperate volcanic step between highland frost and lowland heat. Tlahuica hydraulic works and later Aztec tribute made the site a prize. Cortés understood that: the palace is early colonial military architecture built with Indigenous labor and reused stone, among the oldest surviving civil buildings on the continental mainland. Diego Rivera’s 1930 mural on the east terrace, paid for by U.S. ambassador Dwight Morrow, retells Conquest and Revolution for visitors who might otherwise see only bougainvillea.",
      "Cathedral precincts began as a Franciscan open-chapel complex, a conversion machine for a densely settled Tlahuica valley already used to irrigation. Sugar, then rice and vegetables, tied the municipios of Morelos to Mexico City’s market and to a labor regime of peones on cane haciendas. The climate that Humboldt praised also lengthened the growing season for that cane. Agrarian wealth is why Zapata’s villages fought so hard for restitution: the same frost-light slope that pleased viceroys was a plantation landscape for the people who worked it, a fact the palacio murals still argue.",
      "Twentieth-century Cuernavaca collected exiles, monasteries, language schools, and Mexico City elites seeking winter warmth without coastal humidity. Malcolm Lowry’s novel later mythologized the bars; the material story is the México–Acapulco highway, illegal subdivision on ravines, and aquifer stress as the city became a climate suburb. Popocatépetl’s ashfall and the 2017 earthquake are geophysical neighbors, not rare surprises. Urban growth, not winter cold, is now the binding climate constraint: heat islands, traffic, and water rationing on a slope still marketed as spring.",
      "Morelos remains a short drive from the capital, which keeps land expensive and agriculture squeezed between greenhouses and weekend estates. Ejido remnants still farm the same volcanic soils, but ravines flood in the wet season and run dry trucks in the late drought. A scout should treat the eternal-spring slogan as Humboldt’s lapse-rate observation plus two centuries of elite retreat, then look at drainage, volcano protocols, and whether a given colonia sits on the airy bench or in a hotter, tighter canyon. The Tlahuica hydrology is still the reason the town exists.",
    ],
  },

  "valle-guadalupe-mx": {
    why: "Twenty-five kilometres inland from Ensenada, the valley still catches Pacific marine air through coastal gaps without living inside full upwelling fog. Granitic and alluvial soils drain fast. Summer afternoons run warm enough to ripen wine grapes; nights cool as the marine layer creeps up-valley. Annual rain is thin, on the order of a couple of hundred millimetres, so groundwater and drought—not temperature—set the ceiling. Mexicali’s interior heat and Ensenada’s fog belt both fail a few tens of kilometres away.",
    immersive:
      "Morning air often arrives already cooled, a faint salt edge moving up the Guadalupe corridor while granite shoulders stay dry and bright. By afternoon the same benches can feel inland-hot, vines and olive rows radiating heat until the marine layer returns and outdoor tables become possible again. Winter storms are brief and precious; most of the year the light is hard, the ground pale, and dust lifts on the access roads. Fog rarely owns the day the way it does on the Ensenada waterfront, yet the valley is not desert-interior either. Water trucks, well talk, and fire season are part of ordinary weather, not background. Vintage nights can drop sharply. The climate works for grapes and olives because drainage and diurnal swing cooperate—and because someone is pumping an aquifer that does not refill on a Napa schedule.",
    history: [
      "Kumiai (Kumeyaay) communities occupied this granite valley for millennia; they called a painted overhang Ojá cuñurr. Archaeology places the basin in the long San Dieguito–Kumiai sequence of the California borderlands. Acorn, agave, and seasonal movement across the Sierra Juárez and coastal terraces structured land use, not emptiness waiting for vines. Neighboring Kiliwa and Paipai territories framed the interior. Spanish and later Mexican missions sat at the edge of that world, not at its beginning.",
      "Dominican friar Félix Caballero founded Misión Nuestra Señora de Guadalupe del Norte on 25 June 1834, the last Dominican mission in the Californias and the first after Mexican independence. Friars planted olives, fruit, and vines with Kumiai labor, including help from leader Jatñil, who later led the 1840 destruction of the mission over forced baptism and intrusion. In 1905 Molokan Spiritual Christian families bought former mission ranch land under Porfirio Díaz and farmed wheat, dairy, and grapes until mid-century agrarian reform and ejido grants redistributed much of the valley.",
      "Commercial Baja wine had already started at Santo Tomás in 1888; Italian families such as the Cettos scaled brandy and bulk wine in the twentieth century. Monte Xanic, founded in 1987, marked a shift to bottled, priced Mexican wine. Scores of small bodegas followed, riding restaurants and weekend traffic from Tijuana and San Diego. Ejidatarios, remaining Molokan descendants, Kumiai communities at San Antonio Necua, and investors now compete for the same thin aquifer. The Ruta del Vino is a land-and-water story, not only a tasting map.",
    ],
    deepTitle: "Kumiai wine valley",
    deep: [
      "Mission Guadalupe was short-lived, but it named the valley and proved olives, fruit, and vines on granitic benches with Kumiai labor. After 1840 the site drifted through ranchos until the Russian Colonizing Enterprise of Lower California bought thousands of hectares in 1905 under Díaz. Molokan villages left adobe, orchards, and family names such as Samarin and Bibayoff still visible among tasting rooms. 1930s–1950s land reform created ejidos that grew grain and cattle before vines regained the high-value niche. Each layer still has claimants, and none of them is only scenery.",
      "Hugo d’Acosta’s schools and the 1990s–2010s bodega boom professionalized winemaking while converting former grazing and table-grape land into bottled estates. Nebbiolo, Tempranillo, Grenache, and Bordeaux varieties dominate because nights stay cool enough to keep acidity on a marine-cooled desert margin. That climate advantage is real and local. So is over-extraction from the Guadalupe Valley Aquifer, shared with Ensenada’s municipal demand. New hotels and pools arrived faster than a basin plan. Fire in surrounding chaparral is a dry-season risk, not a rare headline.",
      "Kumiai communities remain in and beside the valley, including San Antonio Necua, with ongoing fights over water, gravel mining, and consultation on winery and hotel development. Treating the Ruta del Vino as empty terroir repeats the mission’s mistake of 1834. Indigenous land here is not a prologue; it is a present jurisdiction under pressure from the same aquifer. A responsible visit starts from that fact, then looks at vines as one more thirsty crop on a marine-cooled desert margin, not as a European fantasy without neighbors.",
      "Relocators chasing a Mediterranean pocket should price water first: trucked supply, well depth, and municipal limits change year to year as Ensenada and the valley pull from the same granite basin. Labor is cross-border and seasonal, tied to harvest and restaurants. Winters are the easy season; late-summer heat, dust, and fire weather are the working climate. The valley is Mexico’s leading wine district by reputation and bottle share, and it is also a small dry catchment with too many straws. That tension, not the tasting-room architecture, is the historical present.",
    ],
  },

  "patzcuaro-mx": {
    why: "A highland lake at about 2140 m sits inside the volcanic Meseta Tarasca, so lapse-rate coolness and water-body moderation work together. Daytime highs stay in the low-to-mid 20s °C; winter nights can fall to single digits. Afternoon wet-season storms nucleate on the rim and cross the water, then nights clear. Nearby Morelia is lower and more urban-warm; Uruapan drops further into avocado heat. The lake is the climate machine, not only the view.",
    immersive: "Pátzcuaro's climate is shaped by altitude and by the great lake at its center. At about 2140 m, daytime highs hover in the low-to-mid 20s °C year-round; nights cool into the single digits in winter, low teens in summer. The wet season brings afternoon storms that build on the volcanic rim and roll across the water, then nights clear enough for a sweater on the plaza. Nearby Morelia is lower and more urban-warm; Uruapan drops further into avocado heat. The Meseta Tarasca — the Purépecha highlands — remains one of the most culturally continuous and climatically mild regions in Mexico. The lake's falling level is the quieter climate story: less water means less moderation, and the shoreline towns feel that before any plaza does.",
    history: [
      "Purépecha (Tarascan) power gathered around Lake Pátzcuaro from the fourteenth century. Tariácuri and his heirs bound Pátzcuaro, Ihuatzio, and Tzintzuntzan into a state that held off the Mexica. Tzintzuntzan, the place of hummingbirds, became the imperial capital; yácata platforms still rise above the shore. Pátzcuaro served as ceremonial center and noble retreat. Copper, obsidian, and lake fisheries supported a dense basin population. This was a capital landscape, not a sleepy village waiting for a bishop.",
      "After Tzintzuntzan’s submission, Nuño de Guzmán had cazonci Tangáxuan II executed in 1530 and wrecked the region. Vasco de Quiroga, first bishop of Michoacán, moved the diocese to Pátzcuaro in the late 1530s and organized hospital-pueblos inspired by Thomas More’s Utopia. He assigned crafts by village to reduce competition: Santa Clara de Cobre still works copper; other towns keep pottery, textiles, or furniture. The cathedral rose on an earlier sacred site. In 1575–80 viceregal power shifted to Valladolid, today’s Morelia.",
      "Lake villages kept Purépecha language, fishing, and the November ofrendas that visitors now crowd, especially on Janitzio. Twentieth-century indigenismo and later Pueblo Mágico tourism packaged the basin while the lake itself shrank under sewage, erosion, and falling inflows. Land reform redistributed hacienda ground unevenly around the meseta. Pátzcuaro today is a municipal market town and heritage center whose climate still follows the water and the volcanoes, even as the waterline tells a harder story than the plazas.",
    ],
    deepTitle: "Purépecha lake",
    deep: [
      "The Relación de Michoacán records a centralized Purépecha kingdom with a professional army and metalwork that outpaced Mexica bronze, a state that held this lake against Tenochtitlan. Ihuatzio’s causeways and Tzintzuntzan’s five yácatas are state architecture, not village mounds. Spanish writers called the people Tarascos; Purépecha is the name in use. Conquest here was collapse after epidemic and Guzmán’s violence, not a single battle. Quiroga’s hospital-pueblos tried to rebuild population and production under Church tutelage. Villages accepted, resisted, and adapted those craft assignments for five centuries.",
      "When the bishopric and College of San Nicolás left for Valladolid, Pátzcuaro lost political rank but kept a dense ceremonial and market role. Basilica, casa de once patios, and island pueblos organized a Catholic–Purépecha calendar. Night fishing with butterfly nets became an emblem later than many brochures admit; the older economy was seine, chinampa-like plots, and lakeshore milpa. Twentieth-century painters and anthropologists arrived looking for a living Mesoamerica and helped freeze a picturesque version that residents still have to work around.",
      "Día de Muertos on the lake is a household and cemetery practice that tourism now times to the hour, with boat schedules printed months ahead. Janitzio’s night is crowded and commercial; smaller pueblos keep quieter vigils that do not need a ticket. Treating the ofrenda as a show misses the point and adds waste to a stressed lake. The honest seasonal story is maize, crafts for cash, and a pilgrimage calendar that predates hotels. Visitors who want the highland climate still owe the basin better sewage politics than a long weekend provides.",
      "Lake Pátzcuaro’s drop in level and rise in water hyacinth and sewage are measured, not anecdotal, and they show up in fish catches as well as in photographs of exposed mud. That hydrology is the climate-resilience problem: less water means less moderation, worse fisheries, and harder lives in Erongarícuaro, Quiroga, and the islands. Avocado expansion on surrounding volcanic slopes competes for rain, labor, and attention. A deep history of this place is Purépecha statecraft, colonial craft assignment, and a lake under pressure—three layers, one basin.",
    ],
  },

  "valle-de-bravo-mx": {
    why: "At about 1850 m, pine-oak slopes already cut lowland heat. The mid-century reservoir then added a local water body that damps daily swing near shore and feeds wet-season humidity. Volcanic rim geometry organizes afternoon convection. Colorines and lower outlets run warmer; Toluca’s higher basin is frostier. Weekend traffic is not climate, but slope aspect, fog on the dam, and storm cells on the rim are. The lake is engineered; the highland comfort is not.",
    history: [
      "Mazahua and Matlatzinca communities farmed this valley under names such as Pameje long before a Franciscan congregation. Mexica expansion under Axayacatl took the region in the 1470s. Around 1530, friar Gregorio Jiménez de la Cuenca founded a settlement later called San Francisco del Valle de Temascaltepec, a name that confused mapmakers with the nearby mining real. A Franciscan convent followed in the early 1600s. Temazcal, milpa, and timber—not a lake—defined the site. The honorific de Bravo, for Nicolás Bravo, came in the nineteenth century.",
      "Agriculture and forestry remained the base until the Comisión Federal de Electricidad’s first major work. The Ixtapantongo–Miguel Alemán hydroelectric system, planned from 1937 and built through the 1940s, dammed the Tilostoc and flooded on the order of 2,900 hectares of valley fields. Local expropriations cut ejido and private plots. A reservoir now called Lake Avándaro turned an inland farming town into a shoreline. Power for industrialization came first; later the same dams fed the Cutzamala water system toward Mexico City.",
      "Mexico City weekenders, sailing clubs, and the 1971 Avándaro rock festival recast the basin as leisure space. Avándaro neighborhoods and slope houses followed. Pueblo Mágico status in 2005 thickened tourism. Mazahua communities and older barrios still sit above a waterline that did not exist in 1940. Paragliding, forests, and a pretty centro are the visible layer. Under them: a hydroelectric landscape that exports electricity and water while importing weekend congestion, septic load, and slope risk.",
    ],
    deepTitle: "Dammed pine lake",
    deep: [
      "Franciscan San Francisco del Valle was a congregation town in a timber-and-maize highland, one of many Temascaltepec-named places in the western Estado de México, distinguished later from the mining real of the same name. Independence-era raids and a minor 1834 millenarian episode left thinner records than the architecture suggests. What is solid is the agricultural valley: irrigation, two harvests in wetter pockets, and wood for the mining towns downslope. The 1940s flood erased that agrarian map under a reservoir sold as scenery.",
      "CFE’s Miguel Alemán system chained Valle de Bravo, Colorines, Ixtapantongo, and related plants as one of the commission’s first large hydroelectric works. Engineers treated the basin as headwater storage for industry, not as a leisure lake. When Mexico City’s aquifer overdraft became undeniable, Cutzamala plumbing turned the same water toward urban taps. Lakeside property values rose because the climate is mild and the Friday drive is possible. Those values sit on a working water machine that can drop the shoreline in drought years and muddy it after storms.",
      "Avándaro 1971, a rock gathering modeled on U.S. festivals, marked the valley as a youth and elite playground and triggered a conservative backlash in national media. From then on, second homes and hotels outpaced local housing around the new shoreline. Mazahua, Matlatzinca, and campesino land on the slopes became the service hinterland for a recreational lake. That class geography is as structural as the dam wall. Paragliding thermals and pine shade are real; so is the labor that keeps the town running when the Mexico City highway clogs.",
      "Living here year-round means wet-season slope stability, dry-season fire on the forest edge, and water-quality fights as weekend population spikes on a reservoir that also serves distant taps. Colorines shows the hydroelectric working class of the system; the centro shows the postcard. A field history should hold both, plus the Mazahua and Matlatzinca names that predate the lake. The climate is highland-and-water. The town, as visitors meet it, is a mid-century infrastructure project with older agrarian roots still visible above the waterline.",
    ],
  },

  "zacatlan-de-las-manzanas-mx": {
    why: "The Sierra Norte de Puebla stands in the Gulf’s path. Elevation near 2040 m cools a tropical latitude into apple weather, while orographic lift wrings mist, drizzle, and a greener wet season than the drier Puebla basin. Nights drop enough for chill hours; days stay mild rather than hot. Fog and slope aspect decide which orchards work. Puebla city, a few hours away, is sunnier, dustier, and less cloud-forest. Dampness and landslide risk are the price of that green.",
    immersive: "Zacatlán is one of those places a flat climate map undersells. It sits high enough, near 2040 m, for cool nights and apple culture, but close enough to the humid Gulf-facing mountains that fog, drizzle, and wet-season clouds keep the landscape green. Afternoons are mild, winters are cool rather than harsh, and the town has a lived orchard identity rather than just a pretty mountain label. Fog and slope aspect decide which rows pay; cider and the August fair are processing strategies for surplus and damaged fruit. Puebla city, a few hours away, is sunnier, dustier, and less cloud-forest. The tradeoff is dampness: landslides, cloudy stretches, and road-and-slope exposure are part of the climate, not an inconvenience on the way to the apples.",
    history: [
      "Totonac polities held this Sierra Norte country by the first millennium, later pressed by Nahua and Chichimeca movements after Tula’s fall. The Nahuatl name Zacatlán, place of zacate grass, stuck. After the Conquest, encomienda under Hernán López de Ávila and repeated congregaciones moved people from Tenamitec to San Pedro Atmatla and, in 1562, to the present town. Franciscans built a monastery. In 1676 the area was reorganized as a República de Indios. Nahua and Totonac communities remain in outlying villages more than in the commercial centro.",
      "Apple trees arrived in the early 1600s and found the Gulf-facing highland useful: cool nights, enough moisture, volcanic soils. Orchards, cider, and later fruit wines became the municipal signature, celebrated in the Feria de la Manzana from 1941. Plum and pear joined the slopes. Livestock and milpa never disappeared. Relojes Centenario, founded by Alberto Olvera Hernández around 1918, turned a metalworking family into Latin America’s first monumental-clock factory, with a flower clock on the zócalo that is civic identity as much as industry.",
      "Pueblo Mágico designation in 2011 packaged tile roofs, clocks, and apples for national tourism. The Barranca de los Jilgueros and Sierra waterfalls sell the relief that also means landslides in wet months. Clockmaking and orchard processing still employ people; so do weekend restaurants. Indigenous-language speakers cluster in rural localities, not in the tourist frame. Zacatlán’s climate story is Gulf moisture lifted into fruit country. Its social story is Totonac–Nahua sierra towns wrapped in a mestizo market center.",
    ],
    deepTitle: "Sierra apple town",
    deep: [
      "Congregación stacked a colonial Catholic town onto sierra farming already practiced by Totonac and Nahua communities. The Franciscan house and later secular clergy administered a landscape of dispersed hamlets that still use Nahuatl in daily life in parts of the municipality. Apple grafting on those slopes was a European crop taking a Gulf cloud climate, not a Spanish garden fantasy. Disease pressure, fog, and ventilation still decide which cultivars pay. Cider, quince sweets, and the August apple fair are processing and market strategies for surplus and damaged fruit.",
      "Alberto Olvera Hernández, from a metalworking family, built his first clocks as a teenager and installed a monumental piece in nearby Chignahuapan in 1919. The Centenario mark, named for the independence centenary, spread across Mexican plazas and public buildings. The factory-museum on Nigromante is industrial heritage in a fruit town, a reminder that Sierra Norte economies were never only picturesque agriculture. Metalwork, orchards, and later tourism sit on the same cool, wet highland that makes both rust and apple scab a maintenance issue.",
      "Road cuts into the Barranca de los Jilgueros and wet-season cloud make access a climate problem as much as a scenic one, with landslide risk on the same slopes that sell viewpoints. Chignahuapan, Aquixtla, and other Sierra towns share the mist belt with local differences in rain and frost. Comparison with dry Puebla city is the right one: same state, different intercept of Gulf flow. Relocators who want sun every afternoon have picked the wrong sierra. Those who want orchard humidity and cool nights are in the right cloud.",
      "Land tenure mixes small orchards, communal holdings, and town lots now priced by Pueblo Mágico visitor demand after 2011. Apple identity can hide labor conditions at harvest and the squeeze of cheaper fruit from elsewhere in Mexico. A deep read keeps Totonac and Nahua villages in the frame, treats clocks as a real factory history, and treats fog as infrastructure: it waters, it rots, it slides slopes. The manzana nickname is earned. It is also a climate and Indigenous sierra story, not a festival logo.",
    ],
  },

  "coatepec-mx": {
    why: "The windward Gulf slope of the Sierra Madre Oriental lifts moist air until it condenses as cloud and drizzle at about 1250 m. That is montane cloud forest weather: mild afternoons, soft nights, and rain totals far above the dry Mexican highlands. Coffee prefers exactly this band—cool enough for quality, wet enough to grow. Xalapa shares the mist; the Veracruz coastal plain below does not. When the cloud deck thins, the town feels ordinary subtropical. When it sits, the forest drips.",
    immersive:
      "Cloud arrives as a temperature drop you feel on the skin before you see it, a grey lid sliding down from the Cofre de Perote massif and snagging on coffee shade. Streets glisten; tile roofs darken; the smell is wet leaf and roast, not dust. Summer afternoons can still reach the upper 20s °C, but the air is thick rather than searing, and thunder often spends itself on the slope before night. Winter mornings are cool enough for a sweater in the parque, rarely a freeze in town. Annual rain is heavy by highland Mexican standards, so mold, mosquitoes, and slick cobbles are ordinary. Sunbreaks feel earned. The coffee belt is a cloud machine with a town inside it.",
    history: [
      "The Nahuatl name Coatepec, on the hill of the serpents, sits on older Totonac settlement along the Xalapa–Mexico corridor. After the Conquest the town was refounded as San Jerónimo Coatepec. Seventeenth-century estates already grew sugar, tobacco, and citrus on the same Gulf slope. Parish construction for San Jerónimo ran from 1684 toward completion in the early 1800s. This was a temperate agricultural step between tierra caliente and the high plateau, not an empty cloud forest waiting for a bean.",
      "In 1808 Cuban coffee plants reached the Coatepec–Xalapa belt, including plantings tied to Tecosolco and Hacienda Zimpizahua, then spread through Teocelo and the cantón. La Orduña and neighboring haciendas scaled Arabica in the nineteenth century. Coatepec became villa in 1848, city in 1886, and a milling and merchant center for altura coffee. Beneficios, bridges, and the Xalapa rail link turned mist into export. Small and medium producers later replaced some of the great estates, especially after Revolution-era land reform.",
      "Twentieth-century price crashes, rust, and competition pushed some slopes toward citrus or pasture, while shade-coffee and tourism kept the centro’s tile-roof identity. INAH’s 2000 zona de monumentos and later Pueblo Mágico branding sell the cloud-town streetscape. Cerro de las Culebras still looks over a working coffee landscape that is also a remnant bosque mesófilo. The climate remains the crop’s reason. The historical present is growers, mill labor, and weekend visitors sharing a wet slope.",
    ],
    deepTitle: "Cloud-forest coffee",
    deep: [
      "Veracruz coffee did not begin as a boutique crop. It was a nineteenth-century agro-export system using Gulf humidity, volcanic soils, and Indigenous and mestizo labor on haciendas such as Zimpizahua, Mahuixtlán, La Orduña, and Bola de Oro. Water-hungry wet mills polluted streams, a documented environmental cost of the beneficio process. Coatepec’s merchants linked the sierra to Xalapa and the port of Veracruz. The town’s architecture—portales, beneficios, parish towers—is coffee capital, not generic colonial charm dropped on a misty hill. Shade coffee is still the slope’s main climate crop.",
      "Land reform after the Revolution fractured some large properties but did not make every plot viable; quality still tracks elevation, shade trees, and how cherry is washed and dried. Cooperatives and family brands now sell to cafés in Xalapa and Mexico City as well as to exporters. Rust outbreaks and erratic rains, including unseasonal dry spells inside a wet climate, are the working risk. Cloud-forest fragments survive in ravines and shade canopies. Full-sun conversion would be a climate and biodiversity loss, not a nostalgic issue.",
      "Xalapa’s urban sprawl and the Veracruz–Mexico corridor press Coatepec from below and above, turning a coffee cabecera into a weekend and commuter edge. Second homes hunt the mist; traffic follows on wet cobbles. The same orographic lid that makes mild afternoons also traps smoke and slows drying of cherry after harvest. Visitors who want relentless sun have misread the cloud-forest setting. Residents budget for mold, roof leaks, mosquitoes, and the pleasure of sleeping cool in a tropical state. Wet cobbles and roof moss are ordinary maintenance.",
      "Totonac and Nahua slope, colonial sugar and tobacco, then two centuries of coffee that reorganized land, labor, and montane forest: that is Coatepec’s field record. The sculpture garden of Las Pozas belongs to another Gulf-slope town; here the monument is a working shade canopy and a parish finished in 1806. Walk Cerro de las Culebras, then ask who picked, who milled, and whether the creek still runs clear after beneficio season. Crop and climate still write the same sentence.",
    ],
  },

  "alamos-mx": {
    why: "Foothills of the Sierra Madre Occidental sit at 406 m, low enough for hot pre-monsoon afternoons, yet they catch a reliable North American Monsoon pulse from July into September. Winters stay dry, bright, and mild by northern Mexican standards. Tropical deciduous forest greens almost overnight when the storms arrive, then browns again. That dry–wet flip, not a gentle spring, is the climate. Heat and drought are the constraints; the colonial stone is the shade strategy.",
    immersive:
      "May and June can feel like a furnace in the arroyos, cicadas loud, the Sierra de Álamos a bare brown wall. Then monsoon cells stack over the foothills and the tropical deciduous forest leafs out in days: palo santo, amapa, and understory going from dust to shade. Afternoons in the wet months still run hot, but nights ease and the town’s portales hold cooler air. Winter days are the easy season—sun, dry streets, nights near 10 °C rather than frost. Birders work the green months; snowbirds work the dry ones. Dust, well depth, and a 37 °C afternoon are ordinary, not exceptions. The climate is a two-act year, and the architecture is a thermal mass response to the first act.",
    history: [
      "Mayo communities along the river that still bears their name used these foothills long before a real de minas. Yaqui territory lay northwest; Guarijío and other sierra peoples used the uplands. Coronado’s 1540 expedition and earlier Spanish probes followed Indigenous trails past the Los Frailes peaks. Jesuit missions on the Mayo, Fuerte, and Yaqui rivers, from the early 1600s, later supplied labor through repartimiento. This was a densely peopled Indigenous frontier, not an empty silver district.",
      "Silver veins at Aduana and related camps were opened in 1683. Nuestra Señora de la Purísima Concepción de Álamos rose the same year as a merchant and mining town between the Mayo and Fuerte. Local Mayo, Yaqui, and mission Indians worked the mines alongside Spaniards; the camp also drew runaways from Jesuit towns. Eighteenth-century output funded churches, portaled mansions, and expeditions farther north. Humboldt noted silver trains leaving this district. Labor and ore, not romance, built the street plan.",
      "Independence, falling grades, and later revolution emptied many houses. Around 1940, U.S. and Canadian buyers began restoring mansions with local masons, a second silver of tourism and retirement. The Festival Alfonso Ortiz Tirado and Pueblo Mágico status in 2005 thickened the calendar. Mayo and Yaqui history is not a museum preface; those nations still live in southern Sonora and still contest land and water. Álamos is a monsoon-edge mining town reused as a heritage refuge, with summer heat that restoration cannot repeal.",
    ],
    deepTitle: "Mayo silver town",
    deep: [
      "Álamos sat in the alcaldía of Ostimuri, a mining jurisdiction between Sinaloa and Sonora, unusually able to recruit nearby Jesuit-mission labor instead of importing workers from central Mexico. That made the real both a magnet and a refuge: some Mayo, Yaqui, and other Indigenous workers came under draft, others fled mission towns to wage work. Haciendas in the Mayo and Fuerte valleys grew grain for the camps. Jesuit–miner conflict over Yaqui and Mayo control was a structural fight about labor, not a side plot in a pretty colonial town.",
      "Aduana’s ruins, the parish, and the Casa de la Cultura mansions are the visible colonial layer of a 1683 real. China trade goods once reached these streets via Gulf ports a week away by pack train. When veins thinned, the town did not vanish so much as pause; families kept keys to houses that lost roofs. Mid-twentieth-century restoration by Mexican and North American buyers favored the centro’s Spanish image and underplayed the Mayo river world that fed it. A walk that never leaves the portales misses the mines and the river.",
      "Yaqui military resistance, deportations under Porfirio Díaz, and later repatriation are part of the same regional history as Álamos silver, not a distant ethnography. Mayo communities along the river faced hacienda expansion on lands already thinned by epidemic. Putting those wars only in side chapters lets the colonial town look serene. It was serene for owners of mines and houses. The foothills remained a frontier of extraction and revolt into the twentieth century, and Yaqui and Mayo nations still live in southern Sonora.",
      "Today’s visitor climate is winter-dry and summer-monsoon, with a real heat hazard in May and June before the rains leaf out the tropical deciduous forest. Services are those of a small Sonoran town plus the Festival Alfonso Ortiz Tirado and a restoration economy. Relocation homework is medical backup, cooling costs, well reliability, and summer power. Bird diversity after the monsoon is a climate fact worth traveling for. The deep story is still silver, missions, and Mayo–Yaqui country—then a carefully restored stage set that needs the forest and the river to make sense.",
    ],
  },

  "todos-santos-mx": {
    why: "A freshwater oasis on Baja’s Pacific side sits in Sonoran Desert latitudes but next to a cool current. Upwelling and onshore flow trim summer peaks relative to the Sea of Cortez shore a short drive east. Winters are dry, bright, and mild. Rain is scarce; hurricanes and tropical storms are the wild cards, especially in late summer. Springs from the Sierra de la Laguna, not rainfall on site, explain the orchards. Drought is the baseline; the oasis is the exception.",
    immersive:
      "Pacific air reaches the arroyo as a cooler, salt-tinged breeze while the Sierra de la Laguna holds a darker green line inland. Midday in town can still feel desert-sharp, glare off plaster, but the thermometer stays below the Cortez-side punishment, and nights drop into a sleepable range. Winter is the generous season: dry light, warm water for swimming if you accept Pacific chill, orchards working because someone is still irrigating. Late summer humidity and the hurricane calendar are the honest counterweight. When a storm comes, the oasis shows as arroyo, not postcard. Most days the story is simpler: desert light, a spring, and a wind that remembers the California Current.",
    history: [
      "Guaycura bands, including Uchití people at this spring, and Pericú groups to the south used the oasis long before a visita. In the Baja deserts, reliable water and tillable ground were the scarce goods. Jesuit Jaime Bravo founded a visita called Todos Santos in 1724 to farm for the La Paz mission. Fruit, cane, and grain moved by burro toward the gulf. The site was a supply node in a mission system, not a beach town.",
      "In 1733 Sigismundo Taraval established Misión Santa Rosa de las Palmas, endowed in honor of Rosa de la Peña. The 1734 Pericú revolt, sparked in part by Jesuit attacks on polygamy and mission control, killed missionaries at southern stations; Taraval fled. Epidemics emptied rancherías. In 1748 the La Paz mission’s remaining neophytes were moved here; the complex took the Pilar name but kept the Todos Santos toponym. Sugar mills later replaced mission fields. By the late nineteenth century several trapiches made panocha and financed brick houses still standing.",
      "Cane collapsed in the twentieth century when sugar ceased to pay on this small oasis. Highway paving in the 1980s opened the valley to La Paz–Cabo traffic and to a new visitor class. Artists and then tourism reused mill buildings, adobe houses, and the old acequias. Pescadero’s fields and the Cerritos surf break extended the map toward the Pacific edge. Hurricanes, including Odile in 2014, remind the peninsula that Pacific cooling does not cancel tropical cyclones. Water rights in the oasis, not the art calendar, remain the older political fact.",
    ],
    deepTitle: "Pacific spring oasis",
    deep: [
      "Jesuit California was a theocratic supply chain stretched along a desert peninsula. Todos Santos mattered because the Sierra de la Laguna feeds pozas in an otherwise dry cape, making fruit, grain, and cane possible. Guaycura and Pericú resistance, then demographic collapse from disease, is the documented human cost of that chain. After Jesuit expulsion in 1768, Franciscans and Dominicans inherited a shrinking Indigenous population. Secularization and land grants turned mission irrigation toward private cane. The parish on the plaza sits on that relocation, not on an empty dune.",
      "Nineteenth-century sugar built the brick chimneys visitors now photograph along the main street. Eight mills at the boom’s height are the usual local count; the landscape still shows mill stacks, panocha memory, and acequias drawn from the spring. When cane ceased to pay, ranching and small irrigated plots of mango, citrus, and vegetables continued. The 1980s art-town story is a thin recent layer over that agrarian oasis. Pescadero’s fields are the same water logic without the galleries, a working reminder of why the settlement exists.",
      "Surf at Cerritos and an expatriate real-estate market pulled the town toward the Pacific edge, where marine influence is stronger and hurricane exposure is also stronger than in the historic arroyo. Ejido and private titles tangle on the coastal strip, a legal climate as local as the fog. Drought years make the spring politics visible: who gets the ditch, who trucks water, who builds pools on an oasis aquifer. Treating Todos Santos as a mild desert spa hides a hydrological town that has always rationed green.",
      "A deep history runs spring, mission, Pericú revolt, sugar mills, highway, and tourism, with Guaycura and Pericú names at the start and a living Mexican farm town under the galleries. Climate-wise, Pacific upwelling is the summer relief and cyclone season is the risk that winter visitors never feel. Bring that pair into any relocation math, along with well depth and ejido title. The oasis is real. It is also finite, and the Sierra de la Laguna is the reason it exists at all.",
    ],
  },

  "tapalpa-mx": {
    why: "A volcanic plateau near 2020 m lifts western Jalisco out of the warm lakes basin. Pine-oak cover and elevation keep summer afternoons often in the low 20s °C, nights cool enough for frost on open flats. Guadalajara’s heat and Colima’s lower valleys do not reach this bench. Wet-season storms and dry-season sun are the two textures. Cabin climate still depends on aspect: a north-facing pine lot is not a cleared ridgetop. The plateau is a lapse-rate island in a generally warmer state.",
    immersive:
      "Pine shade on the Sierra de Tapalpa cuts the glare that rules the lakes country below. Afternoons in town are walkable when Sayula’s basin is not; nights ask for a blanket even in summer, and winter can film the open campos with frost. Wet months turn the plateau loud with runoff—Salto del Nogal and the gullies running hard—then the dry season returns pale grass, dust, and weekend traffic from Guadalajara. Las Piedrotas sit in full wind, a reminder that forest and exposure are different climates a few minutes apart. Wood smoke on cold mornings is ordinary. The highland trick is simple: two kilometres of elevation and a pine lid, not a different latitude.",
    history: [
      "Otomí communities under the señorío of Tzaollan (Sayula) held this sierra; Coca, Pinome, Tzaulteca, and Nahuatl were among languages later recorded. Tapalpa fought in the early-sixteenth-century Guerra del Salitre beside Cuantoma against Purépecha pressure on salt flats. Alonso de Ávalos reached the area in 1523; nearby Atacco submitted without a pitched battle. Franciscans began evangelizing in 1531. The Nahuatl toponym Tlapalpan, land of colored earth, named a highland of pueblos de indios, not a vacant pine park.",
      "Colonial Sierra de Tapalpa mixed at least seven Indigenous towns—including Tapalpa, Atacco, Apango, and Juanacatlán—with haciendas such as Santa María de la Sierra. Land titles came late and poorly for Tapalpa and Atacco compared with neighbors who secured mercedes in the 1560s. Parish San Antonio, tied to a 1683 cédula, marked a shift of Spanish focus from rebellious Atacco to Tapalpa. Through the nineteenth century the municipality remained a timber, livestock, and maize sierra, registered as a town by 1825 and as a municipality by 1869.",
      "Guadalajara’s growth turned the plateau into a weekend cabin belt in the late twentieth century, a short climb out of lake-basin heat. Pueblo Mágico status in 2002 packaged white walls, pine forest, and Las Piedrotas as a national visitor market. Second homes now sit on older agrarian conflict: pueblos de indios versus haciendas, then ejidos versus real-estate. Cool summers are the pitch. The historical present is a small Jalisco highland town managing visitor season, forest, and water on volcanic rock.",
    ],
    deepTitle: "Jalisco pine plateau",
    deep: [
      "Provincia de Ávalos treated this sierra as marginal for sugar and cacao, which is why pine, maize, and livestock persisted instead of plantation monocrops. That marginality preserved a patchwork of Indigenous towns—Tapalpa, Atacco, Juanacatlán, and others—under pressure from expanding haciendas in the seventeenth and eighteenth centuries. Atacco’s memory as the older seat still matters locally, including the shift of the parish. A history that starts with the Magical Town logo skips the land fights that actually produced the municipality. Those fights over mercedes still shape municipal memory.",
      "Timber, charcoal, and livestock linked Tapalpa to lowland markets around Sayula and later Guadalajara. Pine-oak cover is both ecology and fuel history; deforestation and later conservation campaigns are two chapters of the same forest. Cabins in the trees reuse that shade for leisure. Fires in the dry season and road failures in the wet season are the climate maintenance bill. Las Piedrotas, volcanic megaboulders on open grassland, show the plateau without its forest lid—windier, brighter, and more touristed than a north-facing pine lot.",
      "Relocators from Guadalajara often buy the weekend version: cool nights, fireplace, fog in the pines, and a Saturday market. Year-round life adds school logistics, medical runs off the plateau, and a housing market distorted by short stays. Atacco and smaller ranchos show the rural climate without the centro’s restaurants. Snow is rare; frost on open campos is not. Heat-seekers will be disappointed. That is the point of 2020 m in Jalisco, a lapse-rate island above the warm lakes. Weekend fog in the pines is the product people buy.",
      "Deep history here is Otomí and Coca sierra under Tzaollan, Franciscan congregación after 1531, hacienda encroachment, and a twenty-first-century leisure overlay from Guadalajara. The pine plateau climate is genuine and locally specific, a function of elevation rather than latitude. Treat Pueblo Mágico as a marketing date, 2002, not a founding. The colored earth of the Nahuatl name is volcanic soil. The people who named it were already farming it, and Atacco still remembers an older seat. Cabin traffic now writes a new chapter on that soil.",
    ],
  },

  "xilitla-mx": {
    why: "Windward Sierra Madre Oriental at 600 m still intercepts Gulf moisture hard enough to drip. Cloud forest, waterfalls, and 1500 mm-class rainfall follow. Afternoons can be warm-humid, nights mild; this is not a cool highland at 2,000 m. Orographic lift is the whole trick: the same latitude’s interior is far drier. Landslide and flood risk ride with the green. Las Pozas is a garden in that machine, not the machine itself.",
    immersive:
      "Gulf air hits the Huasteca escarpment and turns into noise: water on leaves, water in gullies, water on the convent’s old stone. Xilitla’s streets stay slick when the interior plateau is dust. At 600 m the heat never fully leaves—summer afternoons in the low 30s °C are real—but cloud and shade cut the burn, and nights hold in the teens. Orchids, ferns, and coffee tell the same story as the ruined Augustinian fortress: this slope is wet enough to rot wood and grow almost anything. When a norte or a stalled tropical wave sits on the range, the forest drips for days. Sun is a break, not a default. Bring mold strategy along with the walking shoes.",
    history: [
      "Teenek (Huastec) towns occupied this Sierra Alta; Nahua settlement later added the name Xilitla. Mexica pressure reached the Huasteca in the Late Postclassic. Cortés’s Pánuco campaigns claimed the region; encomiendas followed. Augustinians under Antonio de la Roa began mission work in 1537. Construction of a fortress-convent dedicated to Saint Augustine started in the 1550s because Pame and other Chichimeca raids from the northwest were not theoretical. The convent burned in 1569 and 1587. Teenek communities remained the demographic core in rural localities.",
      "Franciscans later stabilized a parish presence. Coffee and citrus became the municipal cash crops on the same wet slope, with an August coffee fair tied to the patronal calendar. Most residents still live in dozens of small communities, many in Indigenous-language households, not in the cabecera. Edward James, a British poet and surrealist patron, bought a coffee finca near La Conchita with Plutarco Gastélum in the 1940s, first for orchids and animals. A rare 1962 frost killed the orchids; concrete structures then rose among the pools until James’s death in 1984.",
      "Las Pozas opened to visitors in the 1990s and was acquired in 2007 by the Fundación Pedro y Elena Hernández. INAH listed it as an artistic monument in 2012. Tourism now rivals coffee in the cabecera’s economy, while Teenek villages continue milpa, coffee, and labor migration. The surreal garden is a mid-century foreign project on Huastec land and Huastec rainfall. The older town is the convent, the market, and the cloud forest that made both coffee and concrete possible.",
    ],
    deepTitle: "Huastec cloud slope",
    deep: [
      "Xilitla’s Augustinian convent was mission and fort, a typical Huasteca response to the Chichimeca frontier and Pame raids from the northwest. Attacks and fires in 1569 and 1587, then long abandonment, show how thin Spanish control was on this escarpment. Teenek social life re-centered in rural communities that still speak Huastec in large numbers across more than a hundred localities. Any history that treats Las Pozas as the origin of Xilitla inverts the record. The municipality’s population is agrarian and Indigenous first.",
      "Coffee and citrus on these slopes are Gulf orography turned into export crops, as in Coatepec, but at lower elevation and in a Teenek cultural landscape. Zacahuil and the patronal fiesta of Saint Augustine in late August are local civic time, not visitor inventions. Road cuts into karst and mudstone fail in the wet season; that is infrastructure history written by rainfall totals near 1500 mm. Edward James hired local masons—more than a hundred workers at times—to pour a personal surrealism using the same labor pool as the fincas.",
      "Las Pozas occupies some nine hectares of sculpture inside a larger conservation property acquired in 2007 by a private foundation after decades of decay. Stairways to nowhere and concrete flowers now draw international visitors through a small cabecera. Benefits are uneven: hotels in town, continued poverty in outlying Teenek localities, pressure on paths and pools. The 1962 frost that ended James’s orchid garden is a climate data point: even a cloud forest can see a killing cold. Slope failure remains the everyday hazard on this wet escarpment.",
      "A deep read holds Teenek land, Augustinian stone, coffee fincas, and a surrealist folly in one Gulf-facing watershed. Do not exoticize the forest or the people who farm it. The green is orographic lift, not mystery. The garden is one British patron’s fortune plus local masonry skill after a frost. The town’s long-term fit depends on roads, landslides, clinic access, and whether tourism pays more than it extracts from villages beyond the ticket gate. That ledger is still open. Teenek localities beyond the garden still farm the same rain.",
    ],
  },

  "morelia-mx": {
    why: "The Guayangareo valley at about 1920 m on the western Trans-Mexican Volcanic Belt sits in the classic Mexican highland band: afternoons often 24–28 °C, nights 7–13 °C, a June–September thunderstorm season, and a long dry-bright winter. Surrounding relief sharpens local variation, but the city itself is a basin climate, not a canyon microclimate like Guanajuato. Pátzcuaro’s lake sits higher and cooler; Uruapan drops toward avocado heat. Elevation plus subtropical latitude is the whole mechanism.",
    immersive:
      "Pink cantera takes the dry-season sun and gives it back as a warm wall at dusk, while the air itself stays highland-thin and easy to walk. Winter nights bite enough for a jacket in the plaza; they do not bury the city in frost the way Toluca can. From June, towering clouds build over the volcanic rim and drop hard, short rains that leave the cathedral wet and the rest of the evening clear. Dust and brilliance rule the other eight months. Street trees and the aqueduct’s arches make shade, not a forest climate. You feel a capital’s traffic in the same envelope that makes outdoor dinners ordinary. The comfort is real. So is the dry-season thirst of a growing basin.",
    history: [
      "Purépecha and Matlatzinca influence met in the Guayangareo valley without a major pre-Hispanic city on the site. Encomenderos wanted a Spanish town to rival Vasco de Quiroga’s Pátzcuaro. On 18 May 1541 Viceroy Antonio de Mendoza ordered a settlement first called Nueva Ciudad de Mechuacán. Quiroga’s lobbying later reduced it; after his death the bishopric and civil capital moved here around 1578–80 under the name Valladolid. Pink cantera churches and a grid spread across the valley. An aqueduct, rebuilt in the eighteenth century, brought water along a famous arcade.",
      "José María Morelos y Pavón was born in Valladolid; the 1809 conspiracy and Hidalgo’s 1810 anti-slavery decree passed through this elite city. In 1828 it was renamed Morelia. Franciscan, Augustinian, Carmelite, and other convents packed the centro. Independence, Reform, and revolution all left the stone standing while political rank shifted. INAH’s zona de monumentos (1990) and UNESCO inscription of the historic centre in 1991 froze a colonial-capital image that the modern city now surrounds with peri-urban growth toward Tarímbaro and Charo.",
      "Twentieth-century Morelia became a university and state-government hub, gateway to the Meseta Tarasca and, in winter, to monarch reserves farther east on the volcanic belt. Avocado and berry money in Michoacán’s highlands feeds the metro economy even when the centro sells only cantera and cafés. Restoration and tourism occupy the historic core; manufacturing and housing occupy Tarímbaro, Charo, and the highway edges. The climate that makes evening walks easy is the same highland wet–dry rhythm that farmers around the basin still watch for planting.",
    ],
    deepTitle: "Cantera capital",
    deep: [
      "The Pátzcuaro–Valladolid rivalry was a fight over who would rule Michoacán after the Purépecha kingdom’s fall: bishop and pueblo de indios versus encomenderos and a Spanish city. Moving the College of San Nicolás and the cathedral to Guayangareo around 1578–80 decided it. Morelia’s layout is that victory in stone—wide plazas, religious compounds, a planned traza unlike Guanajuato’s mine canyon. Matlatzinca and Purépecha presence in the valley is the archaeological preface INAH still maps under the cantera grid. The aqueduct later made that Spanish victory drinkable.",
      "Morelos’s birth here ties the city to Insurgencia without making colonial Valladolid a rebel capital; it was often royalist and elite, and the 1809 conspiracy was repressed. The name change in 1828 was a liberal civic act honoring a local insurgent. Nineteenth-century Morelia stayed a regional administrative center while mining wealth shone brighter in Guanajuato and Zacatecas. Conservation in the late twentieth century sold that administrative beauty as World Heritage. The aqueduct is both infrastructure and emblem: water on a dry-season highland.",
      "Michoacán’s contemporary violence and avocado frontier are part of the hinterland students and bureaucrats live with, even when the centro feels calm. The historic core can feel insulated; the state does not. Monarch tourism is seasonal and geographically separate, a volcanic-belt extra, not a city industry. Morelia is a functioning capital with hospitals, universities, and an airport inside a mild highland climate, not a smaller Pátzcuaro. Services are the point of this 1920 m basin.",
      "The valley’s plot is Purépecha and Matlatzinca ground, a 1541 Spanish foundation, capital captured from Pátzcuaro around 1580, Insurgencia memory in the name Morelia, and UNESCO-era preservation under urban sprawl. Highland wet–dry weather still brings a real thunderstorm season and real water stress on a growing metro. Walk the cantera at dusk, then look at where the eighteenth-century aqueduct once drank. Administrative stone on volcanic soil is the through-line. Tarímbaro’s sprawl is the newest chapter of the same basin.",
    ],
  },

  "guanajuato-mx": {
    why: "A steep canyon at about 2000 m in the Sierra de Guanajuato creates block-by-block sun and shade that a flat Bajío city never sees. Elevation supplies the mild highland regime: dry most of the year, wet from June to September, afternoons often in the 20s °C. South-facing stairs bake; tunnel mouths stay cool. Continentality is modest compared with Zacatecas farther north. The geometry is the local climate. The mines explain why anyone built inside that geometry.",
    immersive:
      "Shade and sun trade every few dozen steps. A callejón can hold last night’s cool air while the next landing, turned to the afternoon, radiates stored heat from painted walls. At 2000 m the sky is hard; dry-season dust hangs in the cañada until a summer cell dumps on the hills and the subterranean streets show why they exist. Nights drop into jumper weather most of the year. Stairs are the daily climate test as much as the thermometer: mobility, shade, and lungs. When the rain comes, you hear it first in the tunnels. The town is a highland mine camp folded into a ravine, and you feel the fold all day.",
    history: [
      "Otomí farmers and Chichimeca groups, including Guamares, used this sierra before Spaniards found silver. Franciscans passed in the 1540s; a cattle estancia appeared by 1546. Juan de Jaso’s 1552 strikes led to mines by 1557 and a crowded camp of several hundred Spaniards by 1570. Four early foci—Marfil, Tepetapa, Santa Ana, Cerro del Cuarto—grew into a linear town because the ravine forbade a grid. Flood control later buried the river in tunnels that are now streets. Ore, not a civic plan, wrote the map.",
      "La Valenciana, booming after the 1760s–1770s, made Guanajuato a world silver center. Churrigueresque La Compañía and La Valenciana churches, the Alhóndiga de Granaditas, and hillside palaces spent that surplus. Indigenous and mixed mine labor, including drafted workers, underwrote the Baroque. On 28 September 1810, Hidalgo’s insurgents took the Alhóndiga, a founding battle of Independence. Mining staggered through the nineteenth century, revived, and faded; the town remained a state capital in a canyon.",
      "UNESCO inscribed the Historic Town of Guanajuato and Adjacent Mines in 1988. The Festival Internacional Cervantino, from 1972, filled the callejones with another seasonal economy. Tunnels still move cars where the river ran. Marfil and Santa Rosa de Lima show lower-road and higher-forest edges of the same sierra. Tourism and university life now outrank silver, but the shafts, including deep workings at Valenciana, are why the canyon is a city.",
    ],
    deepTitle: "Canyon mine city",
    deep: [
      "Chichimeca War geography matters: silver roads north needed protection, and Guanajuato sat on that violent frontier between Otomí farms and Guamares country. Otomí and later imported labor from central Mexico mixed with local people in the reales de minas. The town’s so-called subterranean streets are hydraulic works after eighteenth-century floods, a climate-infrastructure story UNESCO lists beside the churches. Boca del Infierno’s 600 m shaft is industrial sublime paid for in bodies. Baroque stone is the surface of that cost. Flood tunnels remain the city’s climate infrastructure.",
      "Pípila and the Alhóndiga occupy civic myth because 28 September 1810 made a grain warehouse into the first great battle of Independence. Royalists and silver sat inside; Hidalgo’s insurgents and mine-country recruits sat outside until the granary fell. After Independence, British and then other foreign capital reworked the mines. Flooding, vein exhaustion, and revolution closed chapters. The canyon kept the architecture when the bonanza ended, which is why the World Heritage file reads as a frozen boomtown. Valenciana’s reduced shafts still work under that frozen boom.",
      "Cervantino crowds and tunnel traffic are the living pressures UNESCO flags: high-rises on the upper valley, tourism load, and a historic core that cannot widen because the ravine forbids a grid. Mobility is not a side note; it is the settlement, stairs and lungs included. Anyone relocating needs legs, shade strategy, and a plan for wet-season humidity in a stone cañada. Santa Rosa de Lima’s pine-oak edge is the cooler contrast. Marfil is the lower road corridor with easier access and less postcard texture.",
      "Chichimeca and Otomí sierra, 1550s silver, Valenciana’s eighteenth-century global metal, the 1810 Alhóndiga, and a UNESCO canyon that still mines at a reduced rate: that sequence is why the ravine is a city. Highland dry–wet weather plus extreme sun-and-shade along the stairs is the daily climate. Do not flatten it into a colorful postcard. The color is mine-camp paint on a ravine that floods when the June–September sky opens, which is why the river now runs in tunnels. Stairs and shade remain the daily test of the canyon.",
    ],
  },

  "zacatecas-mx": {
    why: "At about 2440 m, this interior mining ravine sits hundreds of metres above Bajío cities and farther from tropical moisture. Summer afternoons often stall in the low 20s °C; winter nights routinely frost, with hard freezes possible. Annual precipitation stays in a semi-arid band, near 400 mm. Continentality and elevation, not a lake or a marine layer, make the cool. Guadalupe’s flatter edge runs a little warmer. The Bufa is a wind and sun instrument as much as a landmark.",
    immersive:
      "Thin air on the cañada is the first fact: stairs cost more, sun bites harder, and shade is a civic resource. Summer does not cook the stone the way Saltillo’s lower desert can; a 25 °C afternoon feels like the ceiling, not a pause before 35. Winter mornings can glaze the cathedral’s pink cantera with frost, and a norther makes the Bufa cruel. Dry-season light is mineral-sharp; the short wet season smells of dust turned to mud in the alleys. Nights are the reason blankets exist in Mexican hotels. You came for silver Baroque. You stay, if you stay, because the highland is genuinely cool.",
    history: [
      "Zacateco people, a Chichimeca group, lived around the hog-bladder mountain the Spanish called Cerro de la Bufa. Caxcan country lay southwest, still raw from the Mixtón War. On 8 September 1546 Juan de Tolosa was shown silver ore at the Bufa; a camp formed at once. Tolosa, Diego de Ibarra, Cristóbal de Oñate, and Baltasar Temiño de Bañuelos are named as founders of the 1548 town. The rush pulled Indigenous workers from central Mexico and set off the long Chichimeca War to keep the silver road open.",
      "Built without a grid on the Arroyo de la Plata, Zacatecas became one of New Spain’s great silver cities. Franciscan, Augustinian, and Dominican convents, the cathedral’s Churrigueresque façade (1730–60), and steep callejones spent the metal. Mines such as El Edén undercut the centro. In the nineteenth century the city remained a northern capital of Church and commerce. On 23 June 1914 Pancho Villa’s División del Norte took Zacatecas in a decisive Revolutionary battle fought on the Bufa and surrounding hills.",
      "UNESCO listed the Historic Centre in 1993, crediting a townscape moulded to a metalliferous ravine between the Bufa and El Grillo. Mining never fully stopped; tourism, university life, and the Guadalupe metro extension now share the basin. Mina El Edén runs visitors through the industrial layer under the centro. Water, always scarce on this steppe highland, is the long constraint on gardens and growth. The cool climate is elevation, not a marine gift. The city is still a silver argument in pink cantera.",
    ],
    deepTitle: "Bufa silver city",
    deep: [
      "Zacatecas committed New Spain to occupying the Gran Chichimeca: mines required food, mercury, cloth, mule trains, and a defended Camino de la Plata. Zacateco resistance failed against that economic gravity after 1546. Indigenous workers from the south and African labor, wage and coerced, filled the shafts. Colonial studies still frame the point: this was a society organized around silver. Baroque façades that mix European and Indigenous ornament, including the cathedral’s, are that society’s public face, not a separate art history.",
      "The cathedral (1730–60), Santo Domingo, and the Mala Noche palace record boom centuries in a ravine that never took a grid. Economic slump in much of the twentieth century accidentally preserved street pattern and scale, which UNESCO later praised. Villa’s Toma de Zacatecas on 23 June 1914 was a military fact that broke Huerta’s northern hold; bullet scars and the Bufa monument are civic memory. Guadalupe grew as the practical, flatter twin. Vetagrande remains a high, dry mining edge. Pink cantera still records that battle and that slump.",
      "Frost, wind, and 2440 m altitude are daily design problems: steep walking, icy mornings, and a sun that burns through thin air. Semi-arid water accounting, with annual rain near 400 mm, is stricter than in Morelia or Guanajuato. Relocators who want Mexican colonial urbanism without tropical nights find it here, then discover heating bills, dry skin, and winter frost on cantera. The climate is not a mild Cuernavaca. It is a high steppe city with churches and a working mine under the streets.",
      "Zacateco ground, Juan de Tolosa’s 1546 strike, Chichimeca War logistics on the silver road, Baroque spend, Villa’s 1914 battle, and World Heritage listing in 1993 sit together under aquifer stress. Cerro de la Bufa still explains the town: ore, lookout, battlefield, and weather station in one ridge above a narrow cañada. Look up from the cathedral and you are looking at the reason anyone stayed at 2440 m on a dry plateau. Winter frost on the cathedral is the climate receipt.",
    ],
  },

  "saltillo-mx": {
    why: "A Chihuahuan basin at about 1600 m sits only tens of kilometres from Monterrey yet several degrees cooler on summer afternoons because of that extra elevation. Dry air and continentality mean hot days still happen, but nights and winters cool hard, with frost possible. Sierra Madre Oriental foothills at Arteaga wring a little more moisture and orchard weather. The livable pocket is elevation plus a spring. The surrounding desert is the default.",
    history: [
      "Coahuiltecan and other Chichimeca groups used this high desert when Alberto del Canto founded Villa de Santiago del Saltillo in 1577 beside a spring and small waterfall, the salto that named the place. The Spanish villa stayed tiny and exposed. In 1591 Viceroy Luis de Velasco resettled Tlaxcalan allies in autonomous San Esteban de Nueva Tlaxcala across an irrigation ditch, with privileges to bear arms and hold land. Tlaxcalan wheat, irrigation, and weaving kept the dual town alive while Toboso and other nations continued to raid.",
      "San Esteban’s Tlaxcalan population long outnumbered Spanish Saltillo, a dual-town fact that shaped irrigation, defense, and craft. Sarape weaving—Tlaxcalan skill on northern wool, later a trade emblem—moved through the Camino Real fairs that linked central Mexico to Texas and the interior north. Saltillo served as a northern administrative and market hub, at times capital of Coahuila y Tejas. The two towns merged in the 1830s. Agriculture, livestock, and textiles remained the base until rail and then factories reorganized the basin.",
      "Twentieth-century Saltillo became a manufacturing city, including a major automotive cluster that draws comparison with northern industrial belts, while Arteaga’s foothills took orchards, cabins, and cooler air. The historic centro still sits on the spring that named the villa in 1577. Drought and industrial water demand are the climate politics of a Chihuahuan basin. A highland desert capital with Tlaxcalan roots is the accurate origin; the factory overlay came later. Both are true at once, and water limits both.",
    ],
    deepTitle: "High desert capital",
    deep: [
      "Tlaxcalan colonization of the north was imperial policy after 1591: sedentary farmers and soldiers planted as a buffer on a Chichimeca frontier. San Esteban’s legal autonomy, including arms and self-rule under the viceroy, was unusual and fiercely defended. Irrigation ditches between the two towns were a social border as well as a hydraulic one. Weaving the Saltillo sarape grew from that dual city, even if later trade attached the name to blankets made elsewhere. Indigenous Coahuiltecan presence was displaced rather than invited into that bargain.",
      "Nineteenth-century Saltillo lived on wheat, livestock, and the annual fair rather than on a silver strike. U.S. war, Reform, and revolution passed through a dry capital that was never a boomtown like Zacatecas. That relative modesty kept a walkable centro. Twentieth-century industry—engines, cars, appliances—pulled in migrants and sprawl toward Ramos Arizpe, the corridor to Monterrey. Climate advantage over Monterrey, several degrees on summer afternoons, became a selling point for plants and for residents who wanted desert sun without the worst lowland heat.",
      "Arteaga’s apples and cabins show how fast the Sierra Madre Oriental changes the deal: a short drive, more trees, more frost pockets, and a different summer afternoon. The city floor remains Chihuahuan grassland and industry. Dust storms, hard freezes, and summer spikes are all in the envelope at 1600 m. Gardens that ignore desert plants waste an aquifer already claimed by factories. Native and arid-adapted planting is the local horticulture, not a style choice imported from wetter highlands. Arteaga’s cooler nights make the elevation thesis walkable.",
      "A desert spring, a 1577 Spanish villa, a 1591 Tlaxcalan town with legal privileges, sarape trade on the Camino Real, a nineteenth-century merger, and an auto-industrial metro: Saltillo is that stack, not a single origin. The elevation gap with Monterrey is the climate thesis, about 8 °C on a summer afternoon in local lore and in the numbers. Water is the limit. San Esteban’s church and cemetery belong in the same visit as the cathedral, then the Arteaga loop to feel the foothill alternative.",
    ],
  },

  "cuauhtemoc-mx": {
    why: "Central Chihuahua’s plateau at about 2060 m is high, dry, and continental: strong sun, cold winters that can snow, and summers hot by day but cool at night. Chill hours and dry air suit apples once irrigation exists. Rain is modest, near 500 mm, so orchards are a groundwater and well story. The Sierra Tarahumara to the west is a different, more dissected climate. This is temperate-fruit weather in a Mexican latitude because elevation and winter cold say so.",
    immersive:
      "Winter mornings on the plateau can steam at the mouth; frost lies on fence wire and the Sierra Tarahumara is a white-toothed wall to the west. Summer afternoons reach the 30s °C, then the dry air dumps the heat after dark so orchard rows go quiet and cold. Wind is a constant companion on the flats. When rain comes it is often a monsoon burst, not a long drizzle, and the fields answer in a week of green. Apple harvest smells like a northern crop in a Chihuahuan light. Dust, well talk, and a hard freeze risk are the texture. This is not a colonial patio climate. It is a high desert that learned to farm like a cold country.",
    history: [
      "Before it was Ciudad Cuauhtémoc, this was San Antonio de los Arenales, a mestizo ranching and tenant-farming district on Bustillos-basin land west of Chihuahua City. Rarámuri country proper lies farther west in the Sierra Tarahumara, but Rarámuri families have long moved through and into the plateau for work. Spanish and Mexican haciendas claimed the grasslands. The Mexican Revolution scrambled those estates. What arrived next was not a mission town but a negotiated agricultural colony from Canada.",
      "Old Colony Mennonites from Manitoba and Saskatchewan, seeking school and military exemptions after Canadian policy changed, sent delegates to Álvaro Obregón. A privilegium in 1921 promised noninterference. In 1922 chartered trains brought families, stock, and implements to land purchased near San Antonio. Manitoba and Swift Current colonies, named for Canadian origins, laid out Strassendörfer on the dry plateau. Early years punished those who planted as if they were still on the Red River; oats, beans, corn, dairy, and later irrigation found the fit.",
      "Apples became a regional signature as wells, chill hours, and packing sheds scaled in the later twentieth century. Cheese, machinery, and a commercial strip on the road to Colonia Obregón tie Mennonite, mestizo, and Rarámuri labor into one market. Cuauhtémoc city is the Mexican service hub beside the campos. Drought, aquifer drop, and drug-war geography are the present risks. The orchard landscape is irrigated high desert, not a naturally wet fruit belt.",
    ],
    deepTitle: "Mennonite orchard",
    deep: [
      "Obregón’s 1921 privilegium fit a post-revolutionary wish to settle northern land with commercial farmers after foreign haciendas broke. Old Colony Mennonites bought property near San Antonio de los Arenales in 1922; they were not granted empty land. Mestizo campesinos and Rarámuri neighbors were already there. Cross-cultural work—wage labor in orchards, markets, workshops—started immediately even when congregations sought separation. Altkolonier Low German, Spanish, and Rarámuri now share the same highway through the campos. Colony roads still bear Canadian village names on Mexican ground.",
      "Crop failure in the 1920s taught monsoon timing: plant with the June–July rains rather than on a Canadian calendar. Irrigation later unlocked apples, a temperate fruit that needs this plateau’s winter chill hours and dry summer days. Packing plants and Mennonite-owned businesses employ mestizo and Rarámuri workers, a class fact, not a postcard of isolation. Some congregations still restrict vehicles; others run modern orchards and dairies. Internal diversity is the reality under a single outsider label. Cheese and grain remain the other cash crops beside apples.",
      "Lázaro Cárdenas reaffirmed educational and military exemptions after 1930s challenges to Obregón’s deal. Those legal exceptions remain politically sensitive in a secular republic that also needs the grain and fruit. Water for apples is the ecological exception that may not last on a BSk plateau. Treating Cuauhtémoc as quaint cheese country skips aquifer math and the Sierra Tarahumara from which Rarámuri workers come when drought or violence pushes them off the mountains. Well depth is now the orchard’s political fact.",
      "Ranching basin, 1922 colony trains from Manitoba and Saskatchewan, hard adaptation to monsoon-edge BSk rainfall, and an apple industry that made a Mexican city the service center for a transnational farming people: that is the plot, not a colonial plaza or a beach. Climate is cold, high, and dry, with genuine winter. Fruit, frost, wells, and mestizo, Mennonite, and Rarámuri communities share one plateau. Winter snow on the plateau is uncommon but not legendary.",
    ],
  },

  "real-catorce-mx": {
    why: "At 2756 m the Sierra de Catorce is a sky island in Chihuahuan steppe: thin air, cool days, winter nights near freezing, and little rain. Surrounding basins bake; the town does not. Continentality keeps skies clear and diurnal swing wide. The Ogarrio tunnel is access, not climate, but the mountain’s elevation lapse is why a desert state holds a cold town. Wirikuta below is hotter and spiritually central. The refuge is orographic.",
    history: [
      "Guachichil Chichimeca bands moved across this altiplano long before a real de minas. The Wixárika (Huichol) pilgrimage landscape of Wirikuta—birthplace of the sun, country of hikuri—already included the Sierra de Catorce and its desert. Silver found in 1772 produced Real de Catorce, formally a mining town by 1779. The name remembers fourteen soldiers in a Guachichil ambush, or a longer religious title; either way it is a frontier war name. A parish rose between 1790 and 1817. This was a late Bourbon boomtown on a sacred desert.",
      "Nineteenth-century Catorce minted coin, imported luxuries, and at peak held on the order of 15,000 people. Porfirian electrification and pumps, including at Santa Anita, briefly modernized extraction. The Ogarrio tunnel, about 2.3 km through the mountain, opened around 1900 as a haul and access bore. Silver prices and revolution emptied the streets after 1900. A few families stayed, living on tailings and on pilgrims to a St. Francis image in the parish church.",
      "Late-twentieth-century film, tourism, and Pueblo Mágico listing in 2001 refilled some rooms without restoring a mine payroll. Wixárika communities still walk from Jalisco, Nayarit, Durango, and Zacatecas to Cerro Quemado and the desert below for offerings, not for spectacle. Catholic pilgrimage to San Francisco packs October around the parish image. Mining concessions in the Wirikuta reserve, including foreign-backed claims, have faced legal and ritual opposition. A ghost town pitch that ignores that living sacred geography is incomplete.",
    ],
    deepTitle: "Wirikuta mine town",
    deep: [
      "Guachichil resistance belongs to the long Chichimeca Wars that made this altiplano frontier expensive to occupy. By the 1770s Spanish power could finally hold a high silver camp at 2700 m. Labor in the shafts was Indigenous, mestizo, and coerced as elsewhere in the north. Boom architecture—stone houses, a plaza, a mint—still stands because abandonment after 1900 froze it. The Ogarrio tunnel arrival is industrial heritage: 2.3 km of one-way darkness into a car-poor centro. Tailings piles still ring the frozen boomtown streets.",
      "Wirikuta is a declared cultural and ecological reserve covering municipalities around Catorce, Charcas, and Matehuala, including desert below the sierra. Wixárika pilgrimage recreates ancestral routes to where the sun was born; hikuri is sacrament, not a visitor activity to advertise. Respect means staying off ceremonial dates and sites unless invited, and not treating peyote as a souvenir. Catholic San Francisco devotion is another, overlapping pilgrim stream each autumn. The town lives on both calendars plus hotels. Wirikuta’s reserve map is the other title on this mountain.",
      "After the silver-price crash and revolution, Real de Catorce became a service desert: thin clinics, thin water, thin winter heat at 2756 m. Artists and backpackers arrived into that vacuum in the late twentieth century. Second-home and boutique restoration now raise prices without restoring a mine payroll. Reopening industrial mining in the sierra would collide with Wirikuta reserve rules and Wixárika rights already argued in court and ceremony. That fight is current history, not a closed chapter. Thin winter heat is why stone houses still matter.",
      "Guachichil ground, Wixárika sacred desert of Wirikuta, 1770s silver, a Porfirian Ogarrio tunnel, collapse after 1900, and a dual pilgrimage town at 2756 m listed as a Pueblo Mágico in 2001: those layers still share the same cold steppe mountain, clear skies, and little rain. Isolation is the point and the problem: the tunnel is still the gate. Relocating here means choosing scarcity, altitude, and a cultural landscape that is not a visitor’s to redefine as a backdrop. The tunnel remains the only ordinary way in.",
    ],
  },

  "la-paz-mx": {
    why: "Bahía de La Paz faces the warm Gulf of California, so winter days stay near 25 °C and nights mild, while summer puts 35 °C afternoons together with rising humidity. Pacific-side Baja, including Todos Santos, stays cooler in the same months because of upwelling. Hurricane tracks from August into October are a real season, not a footnote. At 10 m elevation there is no lapse-rate rescue. The bay’s shelter helps boats; it does not cancel heat.",
    immersive:
      "Winter light on the malecón is the easy Mexico people advertise: dry, bright, water in view, a sweater at night. By July the same bay feels close and hot; the Cortez does not cool like the Pacific, and the breeze can arrive already warm. Mangroves at the margins smell of salt mud at low tide. Storm season is a calendar you watch, not a rumor—choppy water, then the long wait on a forecast. Most years the rain still totals little, so dust and desalination talk never leave. Espíritu Santo sits on the horizon as a marine fact: clear water, sea lions, and a city that lives between desert and a warm gulf.",
    history: [
      "Pericú and Guaycura peoples used Bahía de La Paz and its islands; pearling and fishing were already practiced when Spaniards arrived. Fortún Ximénez landed in 1533; Cortés failed to plant a colony in 1535. Sebastián Vizcaíno named the bay La Paz in 1596. Isidro de Atondo and Eusebio Kino failed again in 1683 after conflict with residents. Pearls, not farmland, kept Europeans returning. Forced diving and early over-harvest were the first ecological wreck on these beds.",
      "Jesuits Juan de Ugarte and Jaime Bravo founded Misión Nuestra Señora del Pilar de La Paz Airapí in 1720. The mission was sacked in the 1734 Pericú revolt and abandoned in 1748, its people moved to Todos Santos. Independent Mexico later made La Paz the peninsula’s political center. Nineteenth-century helmet diving and companies such as Gastón Vives’s culture operation on Espíritu Santo created a pearl gilded age, then disease and overfishing closed the beds in the 1930s. Hotel Perla (1940) marked a tourist turn after the pearls failed.",
      "Baja California Sur became a state in 1974 with La Paz as capital. Marine tourism—whale sharks in the bay, islands, sport fishing—replaced pearls as the water economy, alongside government payroll. Drought, hurricane landfalls, and growth on a thin aquifer are the urban climate story. The sheltered bay is still the reason for a city on this desert coast. The Pericú world that met Cortés did not survive the mission centuries as a polity; the water did.",
    ],
    deepTitle: "Pearl bay capital",
    deep: [
      "Every early European attempt at La Paz collided with Pericú and Guaycura control of water, food, and the pearl beds. Jesuit success around Loreto did not translate here until a late, weak mission in 1720, sacked in the 1734 revolt. Relocating neophytes to Todos Santos in 1748 admits that the bay was hard to hold as a farming theocracy. Pearling continued around the Church’s restrictions because the shells paid. Indigenous divers did the lethal free-dive work before helmet suits existed.",
      "The late-nineteenth-century helmet-diving boom made La Paz a name in world gem markets, then overfishing and disease ended the beds by the 1930s. Fiction later globalized a pearl morality tale; the archival story is concession, class, and oyster biology. Capital functions and a port kept the town when the gems left. Twentieth-century La Paz grew as a small desert city with a malecón, not as a planned resort on the Cancún model, even after Hotel Perla opened in 1940. The malecón is the civic replacement for the pearl beach.",
      "Espíritu Santo and the bay’s whale shark aggregation are now regulated attractions with real carrying-capacity fights among boats, scientists, and the city. Summer heat on the warm Cortez and cyclone season from August into October shape construction and insurance. Desalination and aquifer politics will decide how large the 1974 state capital can get on a desert coast. Relocators who only sample winter get a false mildness. Live a July–September before calling the climate perfect. Hurricane weeks still empty that same waterfront.",
      "Pericú and Guaycura bay, failed Cortés and Kino colonies, a 1720 Jesuit mission, centuries of pearl extraction, a 1930s biological crash, 1974 statehood, and marine tourism: La Paz is that sequence on a warm-gulf desert with a hurricane season and almost no rain. The contrast with Pacific Todos Santos is the teaching tool: same peninsula, different sea, several degrees of summer difference. Choose the water you actually want to live beside. Winter mildness is not the whole year on this gulf.",
    ],
  },

  "puerto-escondido-mx": {
    why: "Oaxaca’s Pacific coast at 15–16°N is tropical wet–dry: sea-breeze afternoons in the low 30s °C, nights that barely cool, and a hard split between a bone-dry winter half and a convective, hurricane-tinged summer half. Warm water is year-round. Zicatela’s surf is bathymetry plus persistent swell and wind, not a climate classification. Inland Mixtec highlands are cooler; this strand is isothermal coast. Humidity, not a cold month, is the constraint. Puerto Vallarta, farther north on a tighter bay, is a different Pacific geometry.",
    immersive:
      "Dry-season mornings start brown and sharp, the lagoon down, the hills the color of dust, the Pacific a relief you walk toward. By afternoon a sea breeze takes the edge off 32 °C without ever feeling highland. From May the same hills blacken with cloud and then explode green; streets steam, mosquitoes return, and a distant cyclone can rearrange the week. Water stays bath-warm. Nights in the dry months are the only time the air feels generous. Wet-season nights stay close. Fishermen still read the sky the way surfers read the buoys. The year has two textures, not four seasons, and both smell of salt.",
    history: [
      "This coast sat in the hinterland of Mixtec Tututepec, a Late Postclassic empire inland; Chatino and Zapotec communities also farmed the sierra behind. Alvarado’s 1522 campaign, with Zapotec allies from the Isthmus, broke Tututepec. The strand itself stayed lightly settled—little soil, much heat—while Santa María Colotepec (1714) and San Pedro Mixtepec (recognized 1629, moved 1723) held Indigenous municipal rights in the hinterland. Coconut palms arrived via the Manila trade, not as native forest.",
      "Twentieth-century Puerto Escondido, once Punta Escondida, was a fishing camp and intermittent coffee port for Nopala, Juquila, and related highland fincas. Beans came by burro and truck to Bahía Principal and went out by canoe to ships. Nazario Castellanos and Escolástica Valencia are remembered among early watchmen-residents. Jurisdictional fights between Colotepec and Mixtepec over the beach date back generations. Highway 131 from Sola de Vega (dirt, 1961) and Highway 200 in the 1960s opened the bay. Population was still only hundreds in the 1970s.",
      "Surfers found Zicatela in those decades; Mexican pilgrims to Juquila used the new road. A 1970 FONATUR-era expropriation aimed at a planned resort did not become another Cancún. Coffee left the beach as trucks took the crop. Tourism, fishing, and still-unresolved land titles now share the bay. Olive ridley nesting on nearby Oaxaca beaches is a conservation fact beside hotel lighting. The Mixtec and Chatino municipalities behind the surf remain the older political map.",
    ],
    deepTitle: "Mixtec surf coast",
    deep: [
      "Tututepec’s Mixtec state was an inland power with coastal reach, broken by Alvarado in 1522, not a beach culture in the modern sense. Colonial congregaciones kept Indigenous land law alive in Santa María Colotepec and San Pedro Mixtepec, which is why a tourist town still sits inside a communal-title dispute. That legal layer explains messy real estate better than any wave forecast. Chatino country toward Juquila ties the coast to a highland pilgrimage economy that predates surfboards and still fills the highway.",
      "Coffee’s need for a hidden anchorage created warehouses at Bahía Principal and a name, Puerto Escondido, for highland beans from Nopala and Juquila. When Highways 131 and 200 arrived in the 1960s, the port function died and the beach function began. FONATUR’s 1,329-hectare 1970 expropriation shows how close Puerto came to a state-built resort; incomplete follow-through left a more improvised town, for better and worse. Water supply, once a reason people left, had to be engineered before tourism could stick.",
      "Zicatela’s sandbar is now a global surf workplace, with local riders and visiting circuits on a beach that was still a fishing edge in the 1970s. Growth after the 2010s strained sewage, hillsides, and housing for workers who service the boom. Hurricane and swell damage are coastal facts on an Aw shore. Turtle camps on nearby nesting beaches and fishing cooperatives are the other water economies. A history that only follows board shorts misses Mixtec municipal politics still running inland of the malecón.",
      "Mixtec Tututepec coast, colonial Colotepec and Mixtepec land law, coffee lightering, road-era surf, and a 1970 tourist-state project that never became Cancún: the bay still sits inside that legal and climatic envelope. Tropical wet–dry weather brings real cyclone risk and almost no cool month. Heat, humidity, and communal-title due diligence are the relocation homework. The sea breeze is genuine. It does not cool like 1555 m Oaxaca City, a different climate on the other side of the Sierra Madre del Sur. Mixtec municipal politics still outlast the surf calendar.",
    ],
  },

  "merida-mx": {
    why: "A flat limestone plateau a few metres above sea level has no orographic coolness. Winters are warm and dry; summers are hotter and humid with afternoon rains from May through October. Cenotes and caves swallow surface water, so hydrology is underground. Inland position weakens some hurricane winds relative to Cancún or the Campeche coast without removing the risk. Trade-wind dryness in winter is the comfort season. Karst, not elevation, is the local mechanism.",
    immersive:
      "January in the centro is glare and a dry easterly, shirtsleeves at night, the limestone still giving back day’s heat from church walls built of older Maya stone. May turns the same streets into a wet-season machine: 34 °C afternoons, a hard shower, steam rising off the calzada. There is no hill to catch a breeze except the one you make with a fan. Cenote air, when you drop into it, is the only reliably cool indoor-outdoor climate. Hurricane weeks are a shutter-and-wait practice even this far inland. The year divides into drinkable evenings and endurance middays. Shade trees on Paseo de Montejo are infrastructure.",
    history: [
      "Maya T’Hó, also recorded as Ichcaanzihó, occupied several large platforms of cut limestone when Francisco de Montejo el Mozo founded Mérida on 6 January 1542. Spaniards named it for Roman-looking ruins that reminded them of Mérida in Extremadura, then broke those platforms for cathedral and casas. The site sat among dense Maya populations and offered raised ground on an otherwise flat karst plain. Conquest of Yucatán had already taken years of war. The new traza sat on a living city, not on vacant bush.",
      "Colonial Mérida was a garrison-capital of encomiendas, Franciscan convents, and repeated Maya resistance, including Jacinto Canek’s 1761 revolt at Cisteil. Cenotes supplied water. In the Porfiriato, henequen (sisal) fibre for binder twine made Yucatecan haciendas rich; Paseo de Montejo’s mansions spent that boom. Maya and mestizo workers on the plantations saw little of the Belle Époque. The Caste War (1847–1901) devastated the east more than this city, which remained the peninsula’s ladino core.",
      "Lázaro Cárdenas’s 1937 visit pushed henequen land into collective ejidos, ending the gilded plantation order if not rural poverty on exhausted soils. Synthetic fibre later collapsed the sisal market. Mérida grew as a state capital, then as a domestic and foreign relocation city in the twenty-first century, still Maya in language in many surrounding towns. Centro restoration and air-conditioning are the new climate adaptations on a hot limestone plain. The platforms under the streets are still T’Hó.",
    ],
    deepTitle: "Maya limestone city",
    deep: [
      "Diego de Landa and other chroniclers described T’Hó’s platforms as astonishing; the cathedral’s masonry is that astonishment reused, as are house lots cut from Maya stone. Milpa and cenote settlement did not vanish; they were legally subordinated to encomienda and parish. Caste geography put Maya barrios on the city’s edge while Spaniards took the traza. Understanding Mérida requires the surrounding pueblos and sites—Dzibilchaltún nearby, Uxmal farther south—not only the zócalo and Paseo de Montejo. Cenotes under the grid remain the city’s only rivers.",
      "Henequen bound Yucatán to international binder-twine markets and to a brutal plantation labor system on Maya and mestizo workers. Paseo de Montejo’s mansions are a monument to that surplus. When Cárdenas arrived in 1937, breaking haciendas was a federal agrarian act in a region that had kept a caste economy unusually late. Ejidos inherited exhausted soils and a monocrop. The city’s later sprawl covered henequen fields with housing. Green gold is a closed chapter with visible houses. Paseo de Montejo still spends that plantation surplus in stone.",
      "Maya speakers remain a large part of Yucatán’s population; treating the capital as a Spanish-only colonial gem is a visitor error that the surrounding towns contradict every market day. Contemporary growth brings water stress on a karst aquifer that has no rivers, plus garbage and heat-island nights. Inland hurricane damage is real even when the eye stays on the coast. Relocation math should include May–October as the living season, not only January’s dry plazas. January plazas hide the wet-season heat that residents actually live.",
      "Maya T’Hó, a 1542 foundation on cut limestone, colonial war and Jacinto Canek’s 1761 revolt, a Porfirian henequen boom and bust, Cárdenas’s 1937 reform, and a hot karst capital under new migration: the streets still sit on that stack. Tropical wet–dry weather offers almost no relief, and rivers run underground. The cenote is not decoration. It is the hydrology that allowed a city on this plain, and it is still the water story. Air-conditioning is the new climate wall on old Maya limestone.",
    ],
  },

  "bacalar-mx": {
    why: "A long freshwater lagoon on Yucatán’s Caribbean slope sits in tropical wet–dry weather with little annual temperature range. Trade winds in the dry months keep humidity tolerable; wet-season storms and hurricane remnants arrive from either coast. Karst water chemistry, not dye, makes the color banding. Stromatolites and a shallow basin store heat. Chetumal’s bay is saltier and more urban; the reef coast is saltier still. Fresh water at 18°N is the local exception.",
    immersive:
      "Morning on the lagoon is a sheet of stacked blues, almost still, the town a thin limestone edge. Air stays warm at night; a dry-season easterly is what makes the heat usable. After a wet-season cell the surface chops, the jetty smells of rain on warm stone, and the seven colors go milky until the silt drops. There is no hill and no cold month. Shade, water, and a fan are the toolkit. Hurricane weeks empty the malecón and fill the radio. When the weather is ordinary, the lagoon is the air conditioner—narrow, local, and only as healthy as the septic tanks and mangrove fringe around it.",
    history: [
      "Maya settlement used Bakhalal, a place among reeds, as a canoe corridor between Chetumal Bay and inland lagoons. Spanish Salamanca de Bacalar was planted in the 1540s, conventionally 1544–45 under Gaspar Pacheco, as a frontier villa on that water road. Isolation, Maya independence in the interior, and later English logging and piracy from the Belize side kept the town weak. The lagoon was a highway and a hiding place, not a resort.",
      "Yucatán’s governors rebuilt the villa in the 1720s. Construction of the Fuerte de San Felipe, a small bastioned fort, ran from about 1727 to 1733 under Antonio de Figueroa y Silva to hold the eastern coast against British woodcutters and raiders. San Felipe Bacalar became a timber and customs outpost with Maya, Spanish, and Afro-descendant residents. It was among the last local holds to recognize independent Mexico, in the 1830s. The fort’s job was imperial edge-work.",
      "In the Caste War, Maya forces took Bacalar in 1848; after a brief recovery, cruzo’ob fighters stormed it on 20 February 1858 and held the lagoon world for decades. The town emptied toward British Honduras. Twentieth-century Bacalar was a small Quintana Roo settlement until road tourism discovered the colors. Pueblo Mágico promotion and a hotel boom now press stromatolites, water quality, and Maya land on the same shore the fort once watched.",
    ],
    deepTitle: "Lagoon fort town",
    deep: [
      "Bacalar’s colonial job was to be the llave of Yucatán’s east: a fort looking toward Walix, later Belize, and toward Maya polities that had not surrendered the interior. INAH work on San Felipe frames pirates and palo de tinte, but the deeper conflict was who controlled the lagoon canoe route between Chetumal Bay and the lakes. Afro-descendant militiamen and Maya neighbors were part of that frontier society, not extras. The rebuilt museum-fort is a small building with a large hinterland.",
      "The Caste War (1847–1901) was the peninsula’s long Indigenous war, not a brief riot. Maya forces took Bacalar in 1848; after a short recovery, cruzo’ob fighters stormed it on 20 February 1858 and inverted the fort’s purpose. The lagoon became a rebel store and corridor. Chan Santa Cruz politics farther north and British trade to the south framed that hold. Mexican reconquest came only at the turn of the twentieth century. A visitor who sees only turquoise skips a fifty-year war.",
      "Stromatolites in the lagoon are living microbial structures, thousands of years in the making, vulnerable to boat wakes, sewage, and sunscreen chemistry. Tourism after the 2000s, accelerated by Pueblo Mágico promotion, scaled faster than sanitation on a freshwater basin. Maya communities around the municipality still farm and fish the same shore. Hurricane tracks and the 2020s hotel surge are the new siege. Color is a karst optical effect that dies if the water dies. Boat permits and septic rules are now the lagoon’s politics.",
      "Maya Bakhalal, a 1540s Spanish villa, an eighteenth-century fort against British logging, Caste War capture, a quiet timber town, and a sudden freshwater resort: the lagoon still holds all of those chapters. Isothermal tropic weather brings cyclone risk and almost no cool season. The lagoon is a fragile commons, not a private pool. Seven colors are limestone chemistry plus care, or they are a fading postcard on a dying shore. Maya shore communities still farm beside the new hotels.",
    ],
  },
};
